import React, { useEffect } from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import Header from './components/Header';
import Hero from './components/Hero';
import Products from './components/Products';
import Hangars from './components/Hangars';
import Tensile from './components/Tensile';
import Services from './components/Services';
import Contact from './components/Contact';
import Footer from './components/Footer';
import TentsPage from './components/TentsPage';
import HangarsPage from './components/HangarsPage';
import TensilePage from './components/TensilePage';
import './styles/globals.css';

const HomePage = () => {
  useEffect(() => {
    const handleScroll = () => {
      const sections = document.querySelectorAll('.hero, .stats, .structures, .hangars, .tensile, .services, .contact');
      sections.forEach(section => {
        const rect = section.getBoundingClientRect();
        if (rect.top <= window.innerHeight / 2 && rect.bottom >= window.innerHeight / 2) {
          sections.forEach(s => s.removeAttribute('data-bg'));
          section.setAttribute('data-bg', 'active');
        }
      });
    };

    window.addEventListener('scroll', handleScroll);
    handleScroll();
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <>
      <Hero />
      <Products />
      <Hangars />
      <Tensile />
      <Services />
      <Contact />
    </>
  );
};

function App() {
  return (
    <BrowserRouter>
      <div className="App">
        <Header />
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route path="/tents" element={<TentsPage />} />
          <Route path="/hangars" element={<HangarsPage />} />
          <Route path="/tensile" element={<TensilePage />} />
        </Routes>
        <Footer />
      </div>
    </BrowserRouter>
  );
}

export default App;
